from collections import defaultdict, dequeMAX_COUNT_MACHINES = 3history = defaultdict(lambda: deque(maxlen=MAX_COUNT_MACHINES))# для track_id=1 добавляем позиции по кадрамhistory[1].append((100, 200))history[1].append((105, 202))history[1].append((110, 205))history[1].append((115, 207))  # теперь очередь переполненаprint(history[1])# deque([(105, 202), (110, 205), (115, 207)], maxlen=3)# самая первая точка (100, 200) вылетела# track_id=2 ещё не существовал — создастся автоматическиhistory[2].append((50, 60))print(history[2])# deque([(50, 60)], maxlen=3)print(history)# dict_keys([1, 2])